def _is_rgb_channel(value: t.Any) -> bool:
    """Return whether *value* is a valid single RGB color channel.

    A channel must be an integer in the interval [0, 255]. ``bool`` is
    rejected explicitly because it is a subclass of ``int``.
    """
    return (
        isinstance(value, int)
        and not isinstance(value, bool)
        and 0 <= value <= 255
    )


def _interpret_color(color: int | tuple[int, int, int] | str, offset: int = 0) -> str:
    """Translate a color name, 256-color index, or RGB triple to ANSI codes.

    A value is only accepted if it is a known color name, an integer in the
    interval [0, 255], or a sequence of three integers each in [0, 255].
    Anything else raises :exc:`ValueError` with an ``Unknown color`` message.
    """
    if isinstance(color, str):
        try:
            return str(_ansi_colors[color] + offset)
        except KeyError:
            pass
    elif isinstance(color, bool):
        # ``bool`` is a subclass of ``int`` but ``True``/``False`` are not
        # colors, so reject them before the integer check.
        pass
    elif isinstance(color, int):
        if 0 <= color <= 255:
            return f"{38 + offset};5;{color:d}"
    elif isinstance(color, (tuple, list)):
        if len(color) == 3 and all(_is_rgb_channel(c) for c in color):
            r, g, b = color
            return f"{38 + offset};2;{r:d};{g:d};{b:d}"

    raise ValueError(_("Unknown color {colour!r}").format(colour=color))

